const body = $input.first().json.body || $input.first().json;

const idAtendimento = body.id_atendimento || body.atendimento_id || body.session_id || body.sessionId || '';

const telefoneRaw = body.telefone_cliente || body.telefone_contato || body.telefone || '';
const telefoneLimpo = telefoneRaw.toString().replace(/\D/g, '');
const nomePaciente = body.nome_cliente || body.nome_contato || 'Paciente';

const tipoAgenda = (body.tipo_agenda || 'centro').toLowerCase().trim();

const TIMEZONE = 'America/Sao_Paulo';

// REGRAS DE HORÁRIO
// SEG-SEX (1-5): 08h30 às 18h30
// SAB (6):       08h30 às 12h00
// DOM (7):       Fechado
const REGRAS_CENTRO = {
    1: { manha: {ini: {h:8,m:30}, fim: {h:12,m:0}}, tarde: {ini: {h:13,m:15}, fim: {h:18,m:0}} },
    2: { manha: {ini: {h:8,m:30}, fim: {h:12,m:0}}, tarde: {ini: {h:13,m:15}, fim: {h:18,m:0}} },
    3: { manha: {ini: {h:8,m:30}, fim: {h:12,m:0}}, tarde: {ini: {h:13,m:15}, fim: {h:18,m:0}} },
    4: { manha: {ini: {h:8,m:30}, fim: {h:12,m:0}}, tarde: {ini: {h:13,m:15}, fim: {h:18,m:0}} },
    5: { manha: {ini: {h:8,m:30}, fim: {h:12,m:0}}, tarde: {ini: {h:13,m:15}, fim: {h:18,m:0}} },
    6: { manha: {ini: {h:8,m:30}, fim: {h:12,m:0}}, tarde: {ini: {h:0,m:0}, fim: {h:0,m:0}} },
    7: null // Fechado
};
const REGRAS_JARDIM_CANADA = {
    1: { manha: {ini: {h:8,m:30}, fim: {h:12,m:0}}, tarde: {ini: {h:13,m:15}, fim: {h:18,m:0}} },
    2: { manha: {ini: {h:8,m:30}, fim: {h:12,m:0}}, tarde: {ini: {h:13,m:15}, fim: {h:18,m:0}} },
    3: { manha: {ini: {h:8,m:30}, fim: {h:12,m:0}}, tarde: {ini: {h:13,m:15}, fim: {h:18,m:0}} },
    4: { manha: {ini: {h:8,m:30}, fim: {h:12,m:0}}, tarde: {ini: {h:13,m:15}, fim: {h:18,m:0}} },
    5: { manha: {ini: {h:8,m:30}, fim: {h:12,m:0}}, tarde: {ini: {h:13,m:15}, fim: {h:18,m:0}} },
    6: { manha: {ini: {h:8,m:30}, fim: {h:12,m:0}}, tarde: {ini: {h:0,m:0}, fim: {h:0,m:0}} },
    7: null // Fechado
};
const REGRAS_BH = {
    1: { manha: {ini: {h:8,m:0}, fim: {h:12,m:0}}, tarde: {ini: {h:13,m:0}, fim: {h:16,m:30}} },
    2: null, //fechado
    3: null, // Fechado
    4: { manha: {ini: {h:9,m:0}, fim: {h:12,m:0}}, tarde: {ini: {h:13,m:0}, fim: {h:16,m:30}} },
    5: null, // Fechado
    6: null, // Fechado
    7: null // Fechado
};

// CONFIGURAÇÃO DA UNIDADE (3 UNIDADES)
const AGENDAS = {
    centro: {
        id_agenda: 'b85b11c51fc6d68c667854e3aacd2c49fb3275caa188f8eb3bee274bee82a5be@group.calendar.google.com',
        nome_unidade: 'Centro',
        nome_empresa: 'Nuova Odontologia',
        timezone: TIMEZONE,
        regras_horario: REGRAS_CENTRO,
        duracao_servico: 30,
        capacidade_simultanea: 1,
        trava_agendamento: 5,
        trava_remarcacao: 2,
        dias_validos: [1, 2, 3, 4, 5, 6],
        profissional: 'Dra. Brenda / Dra. Amanda / Dra. Rosielma'
    },
    jardim_canada: {
        id_agenda: 'd106912fea68caf079c9411eb0cbbdb3232a7ba74d7a1a46a8de1a68436da11d@group.calendar.google.com',
        nome_unidade: 'Jardim Canadá',
        nome_empresa: 'Nuova Odontologia',
        timezone: TIMEZONE,
        regras_horario: REGRAS_JARDIM_CANADA,
        duracao_servico: 30,
        capacidade_simultanea: 1,
        trava_agendamento: 5,
        trava_remarcacao: 2,
        dias_validos: [1, 2, 3, 4, 5],
        profissional: 'Dra. Sabrina / Dra. Camila / Dra. Rosielma'
    },
    bh: {
        id_agenda: 'b5c13535337cb9c7992051b683a0e371b44bd93686b16ee81c7716fd61eabfbd@group.calendar.google.com',
        nome_unidade: 'Belo Horizonte',
        nome_empresa: 'Nuova Odontologia',
        timezone: TIMEZONE,
        regras_horario: REGRAS_BH,
        duracao_servico: 30,
        capacidade_simultanea: 1, // Mantém 1 por horário exato
        capacidade_turno: 2,      // -> NOVA REGRA: Tranca o turno após 2 agendamentos
        trava_agendamento: 5,
        trava_remarcacao: 2,
        dias_validos: [1, 4], // Somente segunda e quinta
        profissional: 'Dr. Sérgio'
    }
};

const config_agenda = AGENDAS[tipoAgenda] || AGENDAS['centro'];

let dataFinal = '';
let horaFinal = '';
let dataAntigaBusca = null;

const dataRaw = body.data_iso || body.data_inicio || body.data_agendada;
if (dataRaw) {
    let dt = DateTime.fromISO(dataRaw, { zone: TIMEZONE });
    if (!dt.isValid) dt = DateTime.fromFormat(dataRaw, 'dd/MM/yyyy HH:mm', { zone: TIMEZONE });
    if (dt.isValid) {
        dataFinal = dt.toFormat('dd/MM/yyyy');
        horaFinal = dt.toFormat('HH:mm');
    }
}

if (body.data_antiga) {
    let dtAntiga = DateTime.fromISO(body.data_antiga, { zone: TIMEZONE });
    if (!dtAntiga.isValid) dtAntiga = DateTime.fromFormat(body.data_antiga, 'dd/MM/yyyy HH:mm', { zone: TIMEZONE });
    if (dtAntiga.isValid) dataAntigaBusca = dtAntiga.toISO();
}

return {
  json: {
    ...body,
    data_agendada: dataFinal,
    horario_agendado: horaFinal,
    data_antiga_iso: dataAntigaBusca,
    telefone_limpo: telefoneLimpo,
    nome_paciente: nomePaciente,
    unidade_selecionada: 'conquista_sorrisos',
    config_agenda: config_agenda,
    tipo_agenda: tipoAgenda,
    acao_fluxo: body.action,
    id_atendimento:    idAtendimento,
    helena_company_id: '372d5f80-ba1e-4172-9d5a-6c93051dca61'
  }
};

const itemConfig = $('Configuracao Unidades').first().json;
const configAgenda = itemConfig.config_agenda || {};

const TIMEZONE = configAgenda.timezone || 'America/Sao_Paulo';
const DURACAO_MINUTOS = configAgenda.duracao_servico || 30;
const CAPACIDADE_MAXIMA = configAgenda.capacidade_simultanea || 1;
const MIN_GAP_MINUTES = 180; // Pausa mínima entre sugestões para dar variedade ao cliente

const feriados = configAgenda.feriados || [
    "2026-01-01", "2026-02-17", "2026-04-03", "2026-04-21", 
    "2026-05-01", "2026-06-04", "2026-09-07", "2026-10-12", 
    "2026-11-02", "2026-11-15", "2026-12-25"
]; 

const eventosOcupados = $input.all().map(i => i.json);
const agora = DateTime.now().setZone(TIMEZONE);

const horasTrava = configAgenda.trava_agendamento || 2;
const inicioSeguro = agora.plus({ hours: horasTrava });

const isFeriado = (data) => feriados.includes(data.toFormat('yyyy-MM-dd'));

function isSlotAvailable(slotStart) {
    if (isFeriado(slotStart)) return false; 
    let ocupados = 0;
    const slotEnd = slotStart.plus({ minutes: DURACAO_MINUTOS });

    for (const evento of eventosOcupados) {
        if (!evento || !evento.status || evento.status === 'cancelled') continue;
        let iniEvt, fimEvt;

        if (evento.start?.dateTime) {
            iniEvt = DateTime.fromISO(evento.start.dateTime).setZone(TIMEZONE);
        } else if (evento.start?.date) {
            iniEvt = DateTime.fromISO(evento.start.date).setZone(TIMEZONE).startOf('day');
        } else { continue; }

        if (evento.end?.dateTime) {
            fimEvt = DateTime.fromISO(evento.end.dateTime).setZone(TIMEZONE);
        } else if (evento.end?.date) {
            fimEvt = DateTime.fromISO(evento.end.date).setZone(TIMEZONE).endOf('day');
        } else { continue; }

        if (slotStart < fimEvt && slotEnd > iniEvt) ocupados++;
    }
    return ocupados < CAPACIDADE_MAXIMA;
}

function isShiftAvailable(slotStart, regraDia) {
    if (!configAgenda.capacidade_turno) return true; // Se a unidade não tiver limite de turno, libera.

    const minSol = slotStart.hour * 60 + slotStart.minute;
    let turnoAlvo = null;

    if (isSlotInShift(minSol, minSol + DURACAO_MINUTOS, regraDia.manha)) turnoAlvo = regraDia.manha;
    else if (isSlotInShift(minSol, minSol + DURACAO_MINUTOS, regraDia.tarde)) turnoAlvo = regraDia.tarde;

    if (!turnoAlvo) return false;

    // Define os limites reais do turno (ex: 08:00 às 11:30)
    const inicioTurno = slotStart.set({ hour: turnoAlvo.ini.h, minute: turnoAlvo.ini.m });
    const fimTurno = slotStart.set({ hour: turnoAlvo.fim.h, minute: turnoAlvo.fim.m });

    let ocupadosNoTurno = 0;

    for (const evento of eventosOcupados) {
        if (!evento || !evento.status || evento.status === 'cancelled') continue;

        let iniEvt;
        if (evento.start?.dateTime) iniEvt = DateTime.fromISO(evento.start.dateTime).setZone(TIMEZONE);
        else if (evento.start?.date) iniEvt = DateTime.fromISO(evento.start.date).setZone(TIMEZONE).startOf('day');

        // Se o evento existente cai dentro da janela deste turno, soma +1
        if (iniEvt && iniEvt >= inicioTurno && iniEvt < fimTurno) {
            ocupadosNoTurno++;
        }
    }

    return ocupadosNoTurno < configAgenda.capacidade_turno;
}

const getMin = (cfg) => cfg.h * 60 + cfg.m;

function isSlotInShift(minSol, minFimSol, shift) {
    if (!shift || (shift.ini.h === 0 && shift.fim.h === 0)) return false;
    return minSol >= getMin(shift.ini) && minFimSol <= getMin(shift.fim);
}

// Resgata os dados
const dataStr = itemConfig.data_agendada;
const horaStr = itemConfig.horario_agendado;
let horarioSolicitado;

if (dataStr && horaStr) {
    horarioSolicitado = DateTime.fromFormat(`${dataStr} ${horaStr}`, 'dd/MM/yyyy HH:mm', { zone: TIMEZONE });
} else if (itemConfig.data_iso) {
    horarioSolicitado = DateTime.fromISO(itemConfig.data_iso, { zone: TIMEZONE });
} else {
    horarioSolicitado = agora;
}

const solicitouHorarioEspecifico = horarioSolicitado.isValid && horaStr && horaStr !== '00:00';
let solicitadoDisponivel = false;

// Verifica a disponibilidade do horário específico (considerando manhã e tarde)
if (solicitouHorarioEspecifico && horarioSolicitado >= inicioSeguro && !isFeriado(horarioSolicitado)) {
    const diaSem = horarioSolicitado.weekday;
    const regraDia = configAgenda.regras_horario ? configAgenda.regras_horario[diaSem] : null;

    if (regraDia) {
        const minSol = horarioSolicitado.hour * 60 + horarioSolicitado.minute;
        const minFimSol = minSol + DURACAO_MINUTOS;

        const isManha = isSlotInShift(minSol, minFimSol, regraDia.manha);
        const isTarde = isSlotInShift(minSol, minFimSol, regraDia.tarde);

        if ((isManha || isTarde) && isSlotAvailable(horarioSolicitado) && isShiftAvailable(horarioSolicitado, regraDia)){
            solicitadoDisponivel = true;
        }
    }
}

// Lógica de Sugestões Inteligentes
let sugestoes = [];
let cursorDia = solicitouHorarioEspecifico ? horarioSolicitado.startOf('day') : agora.startOf('day');
if (cursorDia < agora.startOf('day')) cursorDia = agora.startOf('day');

let diasVerificados = 0;
const MAX_DIAS_BUSCA = 7;
const MAX_OPCOES = 3;
const periodo = itemConfig.periodo_preferencia || '';

while (sugestoes.length < MAX_OPCOES && diasVerificados < MAX_DIAS_BUSCA) {
    const regraDia = configAgenda.regras_horario ? configAgenda.regras_horario[cursorDia.weekday] : null;

    if (regraDia && !isFeriado(cursorDia)) {
        const turnos = [];

        // Filtra os turnos baseado na preferência do cliente (se houver)
        if (periodo === 'manha' && regraDia.manha) turnos.push(regraDia.manha);
        else if (periodo === 'tarde' && regraDia.tarde) turnos.push(regraDia.tarde);
        else {
            if (regraDia.manha) turnos.push(regraDia.manha);
            if (regraDia.tarde) turnos.push(regraDia.tarde);
        }

        // Procura horários dentro dos turnos válidos
        for (const turno of turnos) {
            // Pula turnos vazios/fechados (ex: Sábado à tarde)
            if (turno.ini.h === 0 && turno.fim.h === 0) continue;

            let loopTime = cursorDia.set({ hour: turno.ini.h, minute: turno.ini.m });
            const fimTurno = cursorDia.set({ hour: turno.fim.h, minute: turno.fim.m });

            while (loopTime.plus({minutes: DURACAO_MINUTOS}) <= fimTurno) {
                if (sugestoes.length >= MAX_OPCOES) break;

                if (loopTime >= inicioSeguro && isSlotAvailable(loopTime) && isShiftAvailable(loopTime, regraDia)) {
                    sugestoes.push(loopTime);
                    loopTime = loopTime.plus({ minutes: MIN_GAP_MINUTES });
                } else {
                    loopTime = loopTime.plus({ minutes: DURACAO_MINUTOS });
                }
            }
            if (sugestoes.length >= MAX_OPCOES) break;
        }
    }
    cursorDia = cursorDia.plus({ days: 1 });
    diasVerificados++;
}

// Montagem da resposta
let respostaFinal = '';
let sugestoesISO = [];

if (solicitadoDisponivel) {
    const fmt = horarioSolicitado.setLocale('pt-BR').toFormat('dd/MM (ccc)');
    const hora = horarioSolicitado.toFormat('HH:mm');
    respostaFinal = `✅ O horário solicitado está disponível!\n\n🗓️ *${fmt}* às *${hora}*\n🏥 Unidade: ${configAgenda.nome_unidade}\n👨‍⚕️ Especialista: ${configAgenda.profissional}\n\nDeseja confirmar o agendamento?`;
    sugestoesISO = [horarioSolicitado.toISO()];
} else {
    if (sugestoes.length > 0) {
        const linhas = sugestoes
            .map(s => `🗓️ *${s.setLocale('pt-BR').toFormat('dd/MM (ccc)')}* às *${s.toFormat('HH:mm')}*`)
            .join('\n');

        if (solicitouHorarioEspecifico) {
            respostaFinal = `O horário solicitado não está disponível. Mas encontrei estas opções na unidade ${configAgenda.nome_unidade}:\n\n${linhas}\n\nQual desses fica melhor para você?`;
        } else {
            const txtPeriodo = periodo ? ` para o período da ${periodo}` : '';
            respostaFinal = `Encontrei estes horários disponíveis na unidade ${configAgenda.nome_unidade}${txtPeriodo}:\n\n${linhas}\n\nAlgum desses funciona para você?`;
        }
    } else {
        respostaFinal = `Não encontrei horários disponíveis nos próximos dias na unidade ${configAgenda.nome_unidade}. Gostaria de tentar olhar para a próxima semana?`;
    }
    sugestoesISO = sugestoes.map(s => s.toISO());
}

return {
    json: {
        resultado: respostaFinal,
        sugestoes_iso: sugestoesISO,
        horario_solicitado_disponivel: solicitadoDisponivel
    }
};

const itemConfig = $('Configuracao Unidades').first();
const dadosOriginais = itemConfig.json;
const configAgenda = dadosOriginais.config_agenda;

const TIMEZONE = configAgenda.timezone || 'America/Sao_Paulo';
// Puxa a duração configurada (30 min)
const DURACAO_MINUTOS = configAgenda.duracao_servico || 30; 
// Puxa a capacidade de cadeiras/salas
const CAPACIDADE_MAXIMA = configAgenda.capacidade_simultanea || 1;

// Eventos ocupados que vêm do Google Calendar
const eventosOcupados = $input.all().map(i => i.json);

const dataStr = dadosOriginais.data_agendada;
const horaStr = dadosOriginais.horario_agendado;
const dataAlvo = DateTime.fromFormat(`${dataStr} ${horaStr}`, 'dd/MM/yyyy HH:mm', { zone: TIMEZONE });

let validacao = { aprovado: false, motivo: '' };
const getMin = (cfg) => cfg.h * 60 + cfg.m;

if (!dataAlvo.isValid) {
    validacao.motivo = 'Data ou hora em formato inválido.';
} else {
    const diaSemana = dataAlvo.weekday;
    const regraDia = configAgenda.regras_horario[diaSemana];

    if (!regraDia) {
        validacao.motivo = `A unidade ${configAgenda.nome_unidade} não tem expediente neste dia da semana.`;
        validacao.aprovado = false;
    } else {
        const minSol = dataAlvo.hour * 60 + dataAlvo.minute;
        const minFimSol = minSol + DURACAO_MINUTOS;

        // NOVA LÓGICA: Verifica se o horário encaixa na Manhã OU na Tarde
        let dentroDoExpediente = false;

        if (regraDia.manha && minSol >= getMin(regraDia.manha.ini) && minFimSol <= getMin(regraDia.manha.fim)) {
            dentroDoExpediente = true;
        }
        if (regraDia.tarde && minSol >= getMin(regraDia.tarde.ini) && minFimSol <= getMin(regraDia.tarde.fim)) {
            dentroDoExpediente = true;
        }

        if (!dentroDoExpediente) {
            validacao.motivo = `Horário fora do expediente da unidade ${configAgenda.nome_unidade}.`;
            validacao.aprovado = false;
        } else {
            const slotInicio = dataAlvo;
            const slotFim = dataAlvo.plus({ minutes: DURACAO_MINUTOS });

            let ocupadosSlot = 0;
            let ocupadosTurno = 0; // Novo contador do turno

            // Definir limites do turno atual para o contador
            let inicioTurno, fimTurno;
            if (regraDia.manha && minSol >= getMin(regraDia.manha.ini) && minFimSol <= getMin(regraDia.manha.fim)) {
                inicioTurno = dataAlvo.set({ hour: regraDia.manha.ini.h, minute: regraDia.manha.ini.m });
                fimTurno = dataAlvo.set({ hour: regraDia.manha.fim.h, minute: regraDia.manha.fim.m });
            } else if (regraDia.tarde && minSol >= getMin(regraDia.tarde.ini) && minFimSol <= getMin(regraDia.tarde.fim)) {
                inicioTurno = dataAlvo.set({ hour: regraDia.tarde.ini.h, minute: regraDia.tarde.ini.m });
                fimTurno = dataAlvo.set({ hour: regraDia.tarde.fim.h, minute: regraDia.tarde.fim.m });
            }

            for (const evento of eventosOcupados) {
                if (!evento || !evento.start || evento.status === 'cancelled') continue;

                let iniEvt = DateTime.fromISO(evento.start.dateTime || evento.start.date).setZone(TIMEZONE);
                let fimEvt = DateTime.fromISO(evento.end.dateTime || evento.end.date).setZone(TIMEZONE);

                // 1. Conta colisão exata (ex: 2 pessoas 14:00)
                if (slotInicio < fimEvt && slotFim > iniEvt) ocupadosSlot++;

                // 2. Conta total de pacientes alocados no turno todo
                if (inicioTurno && fimTurno && iniEvt >= inicioTurno && iniEvt < fimTurno) ocupadosTurno++;
            }

            const limiteTurno = configAgenda.capacidade_turno || 999; 

            if (ocupadosSlot >= CAPACIDADE_MAXIMA) {
                validacao.aprovado = false;
                validacao.motivo = `Infelizmente, este horário exato já foi preenchido na unidade ${configAgenda.nome_unidade}.`;
            } else if (ocupadosTurno >= limiteTurno) {
                validacao.aprovado = false;
                validacao.motivo = `A unidade ${configAgenda.nome_unidade} atingiu o limite de agendamentos para este período (manhã/tarde).`;
            } else {
                validacao.aprovado = true;
                validacao.motivo = 'Sucesso';
            }
        }
    }
}

return { json: { ...dadosOriginais, validacao } };

